INSERT INTO moadbook_games.question_bank
  (question_id,category_id,category,difficulty,prompt,options,correct_index,explanation,source_title,source_url,source_evidence,enabled)
SELECT q.id, q."categoryId", q.category, q.difficulty, q.prompt,
       ARRAY(SELECT jsonb_array_elements_text(q.options)), q."correctIndex", q.explanation,
       COALESCE(NULLIF(q."sourceTitle",''),'تحقق حسابي مباشر'), q."sourceUrl", COALESCE(NULLIF(q."sourceEvidence",''),q."verificationMethod",'مراجعة حسابية داخلية'), true
FROM jsonb_to_recordset($moadbook_questions$[
{"id":"hist-04","categoryId":"history","category":"تاريخ","difficulty":"medium","prompt":"ما اسم البحر الذي هبط فيه المسبار القمري «إيغل» خلال مهمة أبولو 11؟","options":["بحر الهدوء","بحر الأمطار","بحر الصفاء","بحر الأزمات"],"correctIndex":0,"explanation":"هبطت المركبة القمرية إيغل في بحر الهدوء يوم 20 يوليو 1969.","sourceTitle":"Apollo 11 Mission Overview","sourceUrl":"https://www.nasa.gov/history/apollo-11-mission-overview/","sourceEvidence":"تذكر ناسا أن إيغل هبط في بحر الهدوء، وأن أرمسترونغ وألدرين استكشفا سطح القمر في 20 يوليو 1969."},
{"id":"geo-01","categoryId":"geography","category":"جغرافيا","difficulty":"easy","prompt":"أي نهر يُعد من أطول أنهار الأرض؟","options":["نهر النيل","نهر الأمازون","نهر المسيسيبي","نهر اليانغتسي"],"correctIndex":0,"explanation":"تذكر ناسا أن طول النيل يُقدّر بنحو 6,695 كيلومترًا، وأنه من أطول أنهار الأرض، وربما أطولها.","sourceTitle":"Quest for the Source of the Nile","sourceUrl":"https://science.nasa.gov/earth/earth-observatory/quest-for-the-source-of-the-nile-7236/","sourceEvidence":"تقول ناسا إن النيل يقدّر طوله بـ6,695 كم، وهو من أطول أنهار الأرض، إن لم يكن الأطول."},
{"id":"geo-02","categoryId":"geography","category":"جغرافيا","difficulty":"easy","prompt":"ما أعلى جبل على سطح اليابسة؟","options":["جبل كليمنجارو","جبل إيفرست","جبل أكونكاغوا","جبل دينالي"],"correctIndex":1,"explanation":"يصف مصدر هيئة المسح الجيولوجي الأمريكية جبل إيفرست بأنه أعلى جبل على الأرض، ويزيد ارتفاعه على 29,000 قدم.","sourceTitle":"The Water Cycle for Kids: Sublimation Occuring on Top of Mt. Everest","sourceUrl":"https://water.usgs.gov/edu/gallery/watercyclekids/sublimation-everest.html","sourceEvidence":"يذكر المصدر أن إيفرست على الحدود بين نيبال والتبت، وهو أعلى جبل على الأرض، بارتفاع يتجاوز 29,000 قدم (8,840 مترًا)."},
{"id":"geo-03","categoryId":"geography","category":"جغرافيا","difficulty":"medium","prompt":"ما عاصمة أستراليا؟","options":["سيدني","ملبورن","كانبيرا","بيرث"],"correctIndex":2,"explanation":"اختار البرلمان كانبيرا عاصمةً للبلاد، وفقًا للهيئة الوطنية للعاصمة في أستراليا.","sourceTitle":"The Siting and Naming of Canberra","sourceUrl":"https://www.nca.gov.au/education/canberras-history/siting-and-naming-canberra","sourceEvidence":"تنص الصفحة على أن قانون مقر الحكومة الذي أُقر عام 1908 أكد ياس-كانبيرا عاصمةً للأمة، وتصف كانبيرا بأنها العاصمة."},
{"id":"geo-04","categoryId":"geography","category":"جغرافيا","difficulty":"easy","prompt":"أي المحيطات هو الأكبر مساحةً؟","options":["المحيط الأطلسي","المحيط الهندي","المحيط الهادئ","المحيط المتجمد الشمالي"],"correctIndex":2,"explanation":"المحيط الهادئ هو أكبر أحواض المحيطات في العالم، كما أنه الأعمق.","sourceTitle":"What is the largest ocean basin on Earth?","sourceUrl":"https://oceanservice.noaa.gov/facts/biggestocean.html","sourceEvidence":"تذكر الإدارة الوطنية للمحيطات والغلاف الجوي أن المحيط الهادئ هو أكبر أحواض المحيطات وأعمقها، ويغطي نحو 63 مليون ميل مربع."},
{"id":"tech-01","categoryId":"technology","category":"تقنية","difficulty":"easy","prompt":"في صفحة HTML، ما الدور الأساسي للعنصر <main>؟","options":["تمثيل المحتوى الرئيسي للصفحة","إنشاء قائمة التنقل","عرض معلومات التذييل","تحديد بيانات وصفية غير مرئية"],"correctIndex":0,"explanation":"يمثل <main> المحتوى المهيمن المرتبط مباشرة بموضوع المستند أو وظيفته الأساسية.","sourceTitle":"<main>: The Main element","sourceUrl":"https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Elements/main","sourceEvidence":"تعرّف الصفحة <main> بأنه يمثل المحتوى المهيمن من <body> المرتبط بالموضوع المركزي للمستند أو الوظيفة المركزية للتطبيق."},
{"id":"tech-02","categoryId":"technology","category":"تقنية","difficulty":"medium","prompt":"كم يبلغ طول عنوان المصدر أو الوجهة في ترويسة IPv4 وفق RFC 791؟","options":["16 بتًا","32 بتًا","64 بتًا","128 بتًا"],"correctIndex":1,"explanation":"يخصص RFC 791 حقلًا بطول 32 بتًا لكل من عنوان المصدر وعنوان الوجهة.","sourceTitle":"RFC 791: Internet Protocol","sourceUrl":"https://www.rfc-editor.org/rfc/rfc791","sourceEvidence":"في القسم 3.1، يحدد RFC 791 كلاً من Source Address وDestination Address بطول 32 bits."}
]$moadbook_questions$::jsonb) AS q(
  id text, "categoryId" text, category text, difficulty text, prompt text, options jsonb,
  "correctIndex" smallint, explanation text, "sourceTitle" text, "sourceUrl" text, "sourceEvidence" text, "verificationMethod" text
)
ON CONFLICT (question_id) DO NOTHING;
